#!/usr/bin/env node

import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";

import {
  DEFAULT_REALTIME_MODEL,
  RealtimeAgentDb,
  RealtimeTransportError,
  startAgentSession,
  type AgentSessionDeps,
  type AgentStartConfig,
  type RealtimeAgentSession,
} from "./index.js";
import {
  CreateFakeMicrophoneCapture,
  CreateMicrophoneCapture,
  FormatInputDeviceList,
  ListInputDevices,
  type MicrophoneCapture,
} from "./audio_input.js";
import { logEventLine } from "./stdout_logger.js";
import {
  BuildToolCallSet,
  FindUnknownToolNames,
  ParseToolNameArguments,
} from "./tool_sets.js";

const x_connectionLostReason = "connection_lost";

export interface ParsedCliRunOptions
{
  promptFile: string;
  contextFile: string;
  model: string;
  toolNames: string[];
  inputDevice?: string;
  safetyIdentifier?: string;
}

export type ParseCliResult =
  | { action: "run"; options: ParsedCliRunOptions }
  | { action: "list_input_devices" };

export interface CliRunDeps
{
  env?: NodeJS.ProcessEnv;
  createDatabase?: () => RealtimeAgentDb;
  sessionDeps?: Partial<AgentSessionDeps>;
  startSession?: typeof startAgentSession;
  createMicrophoneCapture?: (options: {
    inputDevice?: string;
    onFrame: (pcmBase64: string) => void;
    onError: (error: Error) => void;
  }) => MicrophoneCapture;
  registerSignalHandlers?: boolean;
}

export interface CliRuntime
{
  session: RealtimeAgentSession;
  audioCapture: MicrophoneCapture;
  database: RealtimeAgentDb;
  shutdown(reason: string, code: number): Promise<number>;
}

export function ParseCliArgs(argv: string[]): ParseCliResult
{
  const { values } = parseArgs({
    args: argv.slice(2),
    options: {
      "prompt-file": { type: "string" },
      "context-file": { type: "string" },
      model: { type: "string" },
      tool: { type: "string", multiple: true },
      "input-device": { type: "string" },
      "list-input-devices": { type: "boolean", default: false },
      "safety-identifier": { type: "string" },
    },
    allowPositionals: false,
  });

  if (values["list-input-devices"] === true)
  {
    return { action: "list_input_devices" };
  }

  const promptFile = values["prompt-file"];
  if (promptFile === undefined || promptFile.trim().length === 0)
  {
    throw new CliUsageError("--prompt-file is required.");
  }

  const contextFile = values["context-file"];
  if (contextFile === undefined || contextFile.trim().length === 0)
  {
    throw new CliUsageError("--context-file is required.");
  }

  const rawTools = values.tool;
  const toolValues = rawTools === undefined ? [] : Array.isArray(rawTools) ? rawTools : [rawTools];

  return {
    action: "run",
    options: {
      promptFile,
      contextFile,
      model: values.model ?? DEFAULT_REALTIME_MODEL,
      toolNames: ParseToolNameArguments(toolValues),
      inputDevice: values["input-device"],
      safetyIdentifier: values["safety-identifier"],
    },
  };
}

export class CliUsageError extends Error
{
  constructor(message: string)
  {
    super(message);
    this.name = "CliUsageError";
  }
}

export async function StartCliRuntime(
  options: ParsedCliRunOptions,
  deps: CliRunDeps = {},
): Promise<CliRuntime>
{
  const env = deps.env ?? process.env;
  const apiKey = env.OPENAI_API_KEY;
  if (apiKey === undefined || apiKey.trim().length === 0)
  {
    throw new CliUsageError("OPENAI_API_KEY is required to connect to the OpenAI Realtime API.");
  }

  const unknownTools = FindUnknownToolNames(options.toolNames);
  if (unknownTools.length > 0)
  {
    throw new CliUsageError(`Unknown tool(s): ${unknownTools.join(", ")}`);
  }

  const systemPrompt = await readFile(options.promptFile, "utf8");
  const initialContext = await readFile(options.contextFile, "utf8");

  const database = (deps.createDatabase ?? (() => RealtimeAgentDb.open()))();
  const startSession = deps.startSession ?? startAgentSession;
  const createCapture = deps.createMicrophoneCapture ?? CreateMicrophoneCapture;

  let session: RealtimeAgentSession | undefined;
  let audioCapture: MicrophoneCapture | undefined;
  let shuttingDown = false;

  const shutdown = async (reason: string, code: number): Promise<number> =>
  {
    if (shuttingDown)
    {
      return code;
    }

    shuttingDown = true;
    audioCapture?.stop();

    if (session !== undefined)
    {
      try
      {
        await session.stop(reason);
      }
      catch (stopError)
      {
        const message =
          stopError instanceof Error ? stopError.message : String(stopError);
        console.error(`Failed to stop session: ${message}`);
      }
    }

    database.close();
    return code;
  };

  const agentConfig: AgentStartConfig = {
    systemPrompt,
    initialContext,
    toolCallSet: BuildToolCallSet(options.toolNames),
    model: options.model,
    onEvent: (event, info) =>
    {
      logEventLine({
        sessionId: info.sessionId,
        direction: info.direction,
        event,
      });
    },
    onSessionEnded: (info) =>
    {
      if (info.reason === x_connectionLostReason)
      {
        console.error("Realtime connection lost; session ended.");
        void shutdown(info.reason, 1).then((exitCode) =>
        {
          if (deps.registerSignalHandlers !== false)
          {
            process.exit(exitCode);
          }
        });
      }
    },
  };

  try
  {
    const sessionDeps: AgentSessionDeps = {
      apiKey,
      safetyIdentifier: options.safetyIdentifier,
      database,
      ...deps.sessionDeps,
    };

    session = await startSession(agentConfig, sessionDeps);
  }
  catch (error)
  {
    database.close();

    if (error instanceof RealtimeTransportError)
    {
      throw error;
    }

    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to start realtime session: ${message}`);
  }

  try
  {
    audioCapture = createCapture({
      inputDevice: options.inputDevice,
      onFrame: (pcmBase64) =>
      {
        session?.sendAudioFrame(pcmBase64);
      },
      onError: (captureError) =>
      {
        console.error(`Microphone capture failed: ${captureError.message}`);
        void shutdown("audio_error", 1).then((exitCode) =>
        {
          if (deps.registerSignalHandlers !== false)
          {
            process.exit(exitCode);
          }
        });
      },
    });
    audioCapture.start();
  }
  catch (error)
  {
    await shutdown("audio_setup_error", 1);
    throw error;
  }

  return {
    session,
    audioCapture,
    database,
    shutdown,
  };
}

export async function RunCli(argv: string[], deps: CliRunDeps = {}): Promise<number>
{
  let parsed: ParseCliResult;
  try
  {
    parsed = ParseCliArgs(argv);
  }
  catch (error)
  {
    if (error instanceof CliUsageError)
    {
      console.error(error.message);
      return 1;
    }

    throw error;
  }

  if (parsed.action === "list_input_devices")
  {
    console.log(FormatInputDeviceList(ListInputDevices()));
    return 0;
  }

  try
  {
    const runtime = await StartCliRuntime(parsed.options, deps);

    if (deps.registerSignalHandlers === false)
    {
      return 0;
    }

    return await new Promise<number>((resolve) =>
    {
      const onSignal = (): void =>
      {
        void runtime.shutdown("signal", 0).then(resolve);
      };

      process.once("SIGINT", onSignal);
      process.once("SIGTERM", onSignal);
    });
  }
  catch (error)
  {
    if (error instanceof CliUsageError)
    {
      console.error(error.message);
      return 1;
    }

    if (error instanceof RealtimeTransportError)
    {
      console.error(error.message);
      return 1;
    }

    const message = error instanceof Error ? error.message : String(error);
    if (message.includes("ENOENT") || message.includes("no such file"))
    {
      console.error(`Failed to read prompt or context file: ${message}`);
      return 1;
    }

    console.error(message);
    return 1;
  }
}

async function Main(): Promise<void>
{
  const exitCode = await RunCli(process.argv);
  process.exit(exitCode);
}

const x_invokedPath = process.argv[1] ? path.resolve(process.argv[1]) : "";
const x_entryPath = path.resolve(fileURLToPath(import.meta.url));

if (x_invokedPath === x_entryPath)
{
  void Main();
}

export { CreateFakeMicrophoneCapture };

import { mkdirSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

import type Database from "better-sqlite3";

import type { DatabaseConfig } from "../types.js";

type DatabaseConstructor = typeof Database;

const x_moduleDir =
  typeof __dirname === "string"
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));
const x_require = createRequire(
  typeof __filename === "string" ? __filename : import.meta.url,
);
let x_databaseConstructor: DatabaseConstructor | undefined;

const x_packageRoot = path.resolve(x_moduleDir, "..", "..");

export const DEFAULT_DATABASE_PATH = path.join(
  x_packageRoot,
  "data",
  "realtime-agent.sqlite",
);

const x_sessionsTableSql = `
CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL,
  ended_at TEXT,
  ended_reason TEXT,
  system_prompt TEXT NOT NULL,
  initial_context TEXT NOT NULL,
  tool_call_set_name TEXT,
  tool_names_json TEXT NOT NULL,
  model TEXT NOT NULL,
  session_config_json TEXT NOT NULL
)`;

const x_eventsTableSql = `
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL,
  direction TEXT NOT NULL,
  event_type TEXT NOT NULL,
  event_json TEXT NOT NULL,
  is_audio_buffer_append INTEGER NOT NULL DEFAULT 0
)`;

const x_eventsSessionCreatedAtIndexSql = `
CREATE INDEX IF NOT EXISTS idx_events_session_created_at
ON events(session_id, created_at)`;

const x_eventsEventTypeIndexSql = `
CREATE INDEX IF NOT EXISTS idx_events_event_type
ON events(event_type)`;

export function resolveDatabasePath(config?: DatabaseConfig): string
{
  return config?.path ?? DEFAULT_DATABASE_PATH;
}

export function runMigrations(connection: Database.Database): void
{
  connection.exec(x_sessionsTableSql);
  connection.exec(x_eventsTableSql);
  connection.exec(x_eventsSessionCreatedAtIndexSql);
  connection.exec(x_eventsEventTypeIndexSql);
}

export class RealtimeAgentDb
{
  private m_connection: Database.Database;

  private constructor(connection: Database.Database)
  {
    this.m_connection = connection;
    runMigrations(this.m_connection);
  }

  static open(config?: DatabaseConfig): RealtimeAgentDb
  {
    const databasePath = resolveDatabasePath(config);
    const ensureDirectory = config?.ensureDirectory ?? true;

    if (ensureDirectory)
    {
      mkdirSync(path.dirname(databasePath), { recursive: true });
    }

    const connection = new (GetDatabaseConstructor())(databasePath);
    return new RealtimeAgentDb(connection);
  }

  getConnection(): Database.Database
  {
    return this.m_connection;
  }

  close(): void
  {
    this.m_connection.close();
  }
}

function GetDatabaseConstructor(): DatabaseConstructor
{
  x_databaseConstructor ??= x_require("better-sqlite3") as DatabaseConstructor;
  return x_databaseConstructor;
}

import assert from "node:assert/strict";
import { rmSync } from "node:fs";
import { mkdtemp, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import { DEFAULT_REALTIME_MODEL, type AgentStartConfig } from "../../../src/agent/src/index.js";
import {
  ParseCliArgs,
  RunCli,
  StartCliRuntime,
  type CliRunDeps,
} from "../../../src/agent/src/cli.js";
import { CreateFakeMicrophoneCapture } from "../../../src/agent/src/audio_input.js";
import { buildRealtimeConnectionHeaders } from "../../../src/agent/src/realtime_client.js";
import {
  CreateAgentLoopTestContext,
  OpenConnectedSocket,
} from "../agent_loop/helpers.js";

test("ParseCliArgs requires prompt and context files", () =>
{
  assert.throws(
    () => ParseCliArgs(["node", "realtime-agent"]),
    (error: Error) => error.message.includes("--prompt-file"),
  );

  assert.throws(
    () =>
      ParseCliArgs([
        "node",
        "realtime-agent",
        "--prompt-file",
        "prompt.md",
      ]),
    (error: Error) => error.message.includes("--context-file"),
  );
});

test("ParseCliArgs defaults model to gpt-realtime-2 and parses tool flags", () =>
{
  const parsed = ParseCliArgs([
    "node",
    "realtime-agent",
    "--prompt-file",
    "prompt.md",
    "--context-file",
    "context.md",
    "--tool",
    "echo",
    "--tool",
    "echo,echo",
    "--model",
    "custom-model",
    "--safety-identifier",
    "operator-42",
    "--input-device",
    "15",
  ]);

  assert.equal(parsed.action, "run");
  if (parsed.action !== "run")
  {
    return;
  }

  assert.equal(parsed.options.model, "custom-model");
  assert.deepEqual(parsed.options.toolNames, ["echo", "echo", "echo"]);
  assert.equal(parsed.options.safetyIdentifier, "operator-42");
  assert.equal(parsed.options.inputDevice, "15");
});

test("ParseCliArgs uses default model when omitted", () =>
{
  const parsed = ParseCliArgs([
    "node",
    "realtime-agent",
    "--prompt-file",
    "prompt.md",
    "--context-file",
    "context.md",
  ]);

  assert.equal(parsed.action, "run");
  if (parsed.action !== "run")
  {
    return;
  }

  assert.equal(parsed.options.model, DEFAULT_REALTIME_MODEL);
});

test("ParseCliArgs supports list-input-devices action", () =>
{
  const parsed = ParseCliArgs([
    "node",
    "realtime-agent",
    "--list-input-devices",
  ]);

  assert.equal(parsed.action, "list_input_devices");
});

test("RunCli reports missing OPENAI_API_KEY", async () =>
{
  const dir = await mkdtemp(path.join(os.tmpdir(), "realtime-agent-cli-"));
  const promptFile = path.join(dir, "prompt.md");
  const contextFile = path.join(dir, "context.md");
  await writeFile(promptFile, "system prompt");
  await writeFile(contextFile, "initial context");

  const exitCode = await RunCli(
    [
      "node",
      "realtime-agent",
      "--prompt-file",
      promptFile,
      "--context-file",
      contextFile,
    ],
    { env: {}, registerSignalHandlers: false },
  );

  assert.equal(exitCode, 1);
});

test("RunCli reports unknown tools before connecting", async () =>
{
  const dir = await mkdtemp(path.join(os.tmpdir(), "realtime-agent-cli-"));
  const promptFile = path.join(dir, "prompt.md");
  const contextFile = path.join(dir, "context.md");
  await writeFile(promptFile, "system prompt");
  await writeFile(contextFile, "initial context");

  const exitCode = await RunCli(
    [
      "node",
      "realtime-agent",
