export type EventDirection = "incoming" | "outgoing";

export const DEFAULT_REALTIME_MODEL = "gpt-realtime-2";

export interface RealtimeEvent
{
  type: string;
  [key: string]: unknown;
}

export interface ToolRuntimeContext
{
  sessionId: string;
  toolCallId: string;
  metadata?: Record<string, unknown>;
  log?: (message: string, fields?: Record<string, unknown>) => void;
}

export interface ToolDefinition<TArgs = unknown, TResult = unknown>
{
  name: string;
  description?: string;
  inputSchema: Record<string, unknown>;
  callback: (args: TArgs, ctx: ToolRuntimeContext) => Promise<TResult> | TResult;
}

export interface ToolCallSet
{
  name?: string;
  tools: ToolDefinition[];
}

export interface ConversationEventInfo
{
  sessionId: string;
  direction: EventDirection;
}

export type ConversationEventCallback = (
  event: RealtimeEvent,
  info: ConversationEventInfo,
) => void;

export type AgentEventCallback = (
  event: RealtimeEvent,
  info: ConversationEventInfo,
) => void;

export type ToolLifecyclePhase = "queued" | "started" | "succeeded" | "failed";

export interface ToolLifecycleNotification
{
  sessionId: string;
  toolCallId: string;
  toolName: string;
  phase: ToolLifecyclePhase;
  error?: string;
}

export type ToolLifecycleCallback = (notification: ToolLifecycleNotification) => void;

export type SessionEndedCallback = (info: {
  sessionId: string;
  reason: string;
  session: SessionRow;
}) => void;

export type RealtimeAgentTurnMode =
  | {
      type: "server_vad";
      silenceDurationMs?: number;
      threshold?: number;
      prefixPaddingMs?: number;
      createResponse?: boolean;
      interruptResponse?: boolean;
    }
  | {
      type: "manual";
    };

import type { ConversationEventInfo, RealtimeEvent } from "./types.js";

const x_skipEventType = "input_audio_buffer.append";

export interface LogEventLineInput
{
  sessionId: string;
  direction: ConversationEventInfo["direction"];
  event: RealtimeEvent;
}

export function ShouldLogEvent(event: RealtimeEvent): boolean
{
  return event.type !== x_skipEventType;
}

export function logEventLine(input: LogEventLineInput): void
{
  if (!ShouldLogEvent(input.event))
  {
    return;
  }

  const line = {
    session_id: input.sessionId,
    direction: input.direction,
    event_type: input.event.type,
    event: input.event,
  };

  process.stdout.write(`${JSON.stringify(line)}\n`);
}

