        error: error.message,
      });
      runtimeLogger.Close();
      throw error;
    }

    const message = error instanceof Error ? error.message : String(error);
    runtimeLogger.LogError("realtime_session_start_failed", { error: message });
    runtimeLogger.Close();
    throw new Error(`Failed to start realtime session: ${message}`);
  }

